/**
 * The routes between the regions, as data on the world canvas (lane G).
 * Generated by scripts/art/world_routes.py; do not edit by hand. World px on the
 * v5.3 canvas (11264 x 6912, 8 px cells, a tier is a 32 px face). Not read by the
 * game yet: the region lanes build up to it. Checked by lib/world-routes.test.ts.
 */

export type RouteKind = 'road' | 'path' | 'bar' | 'bridge' | 'causeway';
export type TierChangeKind = 'stair' | 'ramp' | 'switchback';
export type CrossingKind = 'ford' | 'bridge' | 'ferry' | 'causeway' | 'bar' | 'stile' | 'step';
export type LaneId = string;
/** A vertex: x, y (world px, on the 8 px grid), width (px), tier. */
export type RoutePoint = readonly [number, number, number, number];
export interface TierChange {
  at: readonly [number, number];
  s: number;
  kind: TierChangeKind;
  from: number;
  to: number;
  run: number;
}
export interface Crossing {
  kind: CrossingKind;
  name: string;
  way: string | null;
  at: readonly [number, number];
  s: number;
  span: number;
}
export interface SidePath {
  obstacle: string;
  at: readonly [number, number];
  leaves: readonly [number, number];
  rejoins: readonly [number, number];
  points: readonly (readonly [number, number])[];
  width: number;
}
export interface PocketPath {
  holds: string;
  clearing: readonly [number, number];
  leaves: readonly [number, number];
  points: readonly (readonly [number, number])[];
  length: number;
  width: number;
  clearingRadius: number;
}
export interface WorldRoute {
  id: string;
  name: string;
  kind: RouteKind;
  from: string;
  to: string;
  length: number;
  walkS: number;
  blockout: { walkS: number | null; tierChanges: number };
  points: readonly RoutePoint[];
  changes: readonly TierChange[];
  crossings: readonly Crossing[];
  sidePaths: readonly SidePath[];
  pockets: readonly PocketPath[];
}
export interface Threshold {
  id: string;
  name: string;
  route: string;
  at: readonly [number, number];
  s: number;
  brief: readonly [number, number];
  object: string;
  band: string;
  landmark: string;
  landmarkAt: readonly [number, number];
  residents: string;
  radiatesFrom: string;
  sides: readonly [LaneId, LaneId];
  objectBy: LaneId;
  bandFade: number;
}
export interface RouteMeet {
  route: string;
  from: LaneId;
  fromPart: string;
  to: LaneId;
  toPart: string;
  at: readonly [number, number];
  cell: readonly [number, number];
  s: number;
  tier: number;
  width: number;
  heading: number;
}
export interface Footprint {
  owner: LaneId;
  part: string;
  box: readonly [number, number, number, number];
}
export interface RouteStop {
  name: string;
  at: readonly [number, number];
}
export interface RouteLink {
  name: string;
  from: string;
  to: string;
  way: string;
}
export interface GateStep {
  open: string;
  reached: readonly string[];
}

